// src/modules/budgets/budgets.service.ts
var import_dayjs = __toESM(require_dayjs_min(), 1);
var budgetsService = {
  async getAllBudgets(filters) {
    const { limit, page, search } = filters;
    const whereCondition = search ? {
      OR: [{ name: { contains: search, mode: "insensitive" } }]
    } : {};
    return prisma.budgets.paginate({
      where: whereCondition,
      page,
      limit,
      orderBy: { createdAt: "desc" }
    });
  },
  async createBudget(userId, payload) {
    const data = {
      name: payload.name,
      periodStart: import_dayjs.default(payload.periodStart, "YYYY-MM-DD").format("YYYY-MM-DD hh:ii:ss"),
      periodEnd: import_dayjs.default(payload.periodEnd, "YYYY-MM-DD").format("YYYY-MM-DD hh:ii:ss"),
      user: {
        connect: {
          id: userId
        }
      }
    };
    return prisma.budgets.create({
      data
    });
  },
  async updateBudget(data) {
    return prisma.budgets.update({
      where: { id: Number(data.id) },
      data: {
        name: data.name,
        periodStart: import_dayjs.default(data.periodStart, "YYYY-MM-DD").format("YYYY-MM-DD hh:ii:ss"),
        periodEnd: import_dayjs.default(data.periodEnd, "YYYY-MM-DD").format("YYYY-MM-DD hh:ii:ss")
      }
    });
  }
};

// src/modules/budgets/budgets.route.ts
var budgetsRouter = new OpenAPIHono().openapi(getAllBudgets, async (c) => {
  const queryFilter = c.req.valid("query");
  try {
    const result = await budgetsService.getAllBudgets(queryFilter);
    return c.json({
      status: "success",
      ...result
    });
  } catch (error) {
    return c.json({ status: "error", message: String(error) }, 500);
  }
}).openapi(createBudget, async (c) => {
  const currentUser = c.get("user");
  const jsonBody = c.req.valid("json");
  try {
    const budget = await budgetsService.createBudget(currentUser.id, jsonBody);
    return c.json({
      status: "success",
      message: "Budget created successfuly",
      data: budget
    });
  } catch (error) {
    return c.json({ status: "error", message: String(error) }, 500);
  }
}).openapi(updateBudget, async (c) => {
  const jsonBody = c.req.valid("json");
  try {
    const updatedBudget = await budgetsService.updateBudget(jsonBody);
    return c.json({
      status: "success",
      message: "Budget has been updated successfuly",
      data: updatedBudget
    });
  } catch (error) {
    return c.json({ status: "error", message: String(error) }, 500);
  }
});

// src/routes/protected.route.ts
var protectedRoute = new OpenAPIHono;
protectedRoute.use("*", async (c, next) => {
  const session = await auth.api.getSession({ headers: c.req.raw.headers });
  if (!session) {
    return c.body(null, 401);
  }
  c.set("user", session.user);
  c.set("session", session.session);
  await next();
});
protectedRoute.get("/session", (c) => {
  const session = c.get("session");
  const user = c.get("user");
  return c.json({
    session,
    user
  });
});
protectedRoute.get("/pg-test", async (c) => {
  try {
    const data = await prisma.user.findMany({
      take: 5
    });
    return c.json({
      status: "success",
      message: "database connection successfully",
      data
    });
  } catch (error) {
    return c.json({
      status: "error",
      message: "Gagal terkoneksi ke database",
      error: error instanceof Error ? error.message : String(error)
    }, 500);
  }
});
protectedRoute.route("/users", usersRouter);
protectedRoute.route("/budgets", budgetsRouter);

